     1	// Room 15: Primary bathroom, interior designer. Inner air x36..39 z24..27 (chimney chase x40..42 z24..26 reserved),
     2	// y7..9. Entry: door at z23 (x38..39, y7..8) from the closet. Window in the back wall z28 (x37..39).
     3	// Layout: double vanity on the west wall (x36, z24..26) with a toilet at the back-left corner; a soaking tub under
     4	// the window (x38..39 z27) as the focal piece; a walk-in shower in the east corner (glass screen on x38 z25..26);
     5	// lanterns on the vanity and on the tub. Column x37 is the clear 2-high path from the door to every fixture.
     6	// Palette only: smooth_quartz, white_concrete, glass_pane, lantern.
     7	import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
     8	
     9	const SMOOTH_QUARTZ = "smooth_quartz";
    10	const WHITE_CONCRETE = "white_concrete";
    11	const GLASS_PANE = "glass_pane";
    12	
    13	export function build(g) {
    14	  // Double vanity: a three-cell counter on the west wall, mirror above it, one lantern between the basins.
    15	  g.fill([36, 7, 24], [36, 7, 26], SMOOTH_QUARTZ);
    16	  g.fill([36, 8, 24], [36, 8, 24], GLASS_PANE);
    17	  g.fill([36, 8, 26], [36, 8, 26], GLASS_PANE);
    18	  g.fill([36, 9, 24], [36, 9, 26], GLASS_PANE);
    19	  g.set(36, 8, 25, ...B.lantern(false));
    20	
    21	  // Toilet: a quartz seat at the back-left corner, its tall back against the west wall (facing west).
    22	  g.set(36, 7, 27, ...B.stairs(SMOOTH_QUARTZ, "west", "bottom"));
    23	
    24	  // Soaking tub under the window: the focal piece, lit by a lantern on its rim.
    25	  g.fill([38, 7, 27], [39, 7, 27], WHITE_CONCRETE);
    26	  g.set(38, 8, 27, ...B.lantern(false));
    27	
    28	  // Walk-in shower: quartz tray in the east corner, glass screen on its west side (x38, z25..26).
    29	  g.fill([39, 7, 25], [39, 7, 26], SMOOTH_QUARTZ);
    30	  g.fill([38, 7, 25], [38, 9, 26], GLASS_PANE);
    31	}
---
     1	// Room 13: Primary bedroom, interior designer. Inner air x36..42 z8..15 y7..9 (walk y7..8); arch in the west wall at
     2	// z14..15 from the upper hall; the turret-bay alcove x38..40 z5..6 opens north-to-south through z7 at x38..40.
     3	// Layout (all cells inside the room box or the alcove, nothing over the east window x43 z11..13 or the bay opening):
     4	//   west wall x35: king bed, headboard on the wall at x36..37 z9..10, nightstands with lanterns at z8 and z11.
     5	//   north wall z7: dresser (spruce chest run) at x40..42 z8 with a slab top.
     6	//   east: open floor under the window, kept clear so the glass reads.
     7	//   centre: pendant lantern on a chain over the walking space at x39 z11.
     8	//   alcove: sitting pair: a slab table at x39 z5, a stair seat at x39 z6 facing the table, lantern on the table.
     9	// Palette note: the palette has no bed, barrel, carpet or flower pot, so the bed is a spruce-plank platform with
    10	// smooth-quartz pillows and mattress, and the dresser is spruce planks with a slab top. Both use palette ids only.
    11	import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
    12	
    13	const SPRUCE_PLANKS = "spruce_planks";
    14	const SMOOTH_QUARTZ = "smooth_quartz";
    15	
    16	export function build(g) {
    17	  // ---- king bed: headboard on the west wall (x36 = head, x37 = foot), 2 wide along z (z9..10) -----------------
    18	  for (const x of [36, 37]) for (const z of [9, 10]) g.set(x, 7, z, SPRUCE_PLANKS);           // frame
    19	  for (const z of [9, 10]) {
    20	    g.set(36, 8, z, SMOOTH_QUARTZ);                                                          // pillows at the head
    21	    g.set(37, 8, z, ...B.slab("smooth_quartz", "bottom"));                                   // mattress at the foot
    22	  }
    23	
    24	  // ---- nightstands flanking the headboard, each with a standing lantern ------------------------------------
    25	  for (const z of [8, 11]) {
    26	    g.set(36, 7, z, SPRUCE_PLANKS);
    27	    g.set(36, 8, z, ...B.lantern(false));
    28	  }
    29	
    30	  // ---- dresser against the north wall: planks run x40..42 at z8 with a slab top -----------------------------
    31	  for (const x of [40, 41, 42]) {
    32	    g.set(x, 7, 8, SPRUCE_PLANKS);
    33	    g.set(x, 8, 8, ...B.slab("spruce", "bottom"));
    34	  }
    35	
    36	  // ---- bench at the foot of the bed (x38 z9..10), a bottom slab on the floor
    37	  for (const z of [9, 10]) g.set(38, 7, z, ...B.slab("spruce", "bottom"));
    38	
    39	  // ---- centre pendant over the walking space: chain from the ceiling, hanging lantern below -----------------
    40	  g.set(39, 9, 11, ...B.chain("y"));
    41	  g.set(39, 8, 11, ...B.lantern(true));
    42	
    43	  // ---- sitting area in the turret-bay alcove (x38..40 z5..6) ---------------------------------------------------
    44	  g.set(39, 7, 5, ...B.slab("spruce", "bottom"));                    // table
    45	  g.set(39, 8, 5, ...B.lantern(false));                              // table lamp on the slab
    46	  g.set(39, 7, 6, ...B.stairs("spruce", "south", "bottom"));         // seat facing the table, back to the room
    47	}

