  1	// Part 1: Shell and massing. Plinth, floors, outer walls of the garage, main block and entry sides, the turret bay,
  2	// interior partitions, ceilings at y10 and the main staircase. Every OPENINGS cell stays air for later parts, and so
  3	// does the chimney chase. The lawn is laid by build.mjs.
  4	import {
  5	  BIRCH_PLANKS, COBBLESTONE, OAK_PLANKS, POLISHED_ANDESITE, SMOOTH_QUARTZ, SPRUCE_PLANKS, STONE_BRICKS,
  6	  CHIMNEY, bay, mainStair,
  7	} from "../vocab.mjs";
  8	
  9	// Inclusive boxes [x0, x1, y0, y1, z0, z1] that the shell leaves empty (plan.md OPENINGS).
 10	const OPENING_BOXES = [
 11	  // garage front (z5): three carriage doors and the bonus-room windows
 12	  [2, 5, 1, 4, 5, 5], [7, 10, 1, 4, 5, 5], [12, 15, 1, 4, 5, 5],
 13	  [2, 4, 7, 9, 5, 5], [7, 9, 7, 9, 5, 5], [12, 14, 7, 9, 5, 5],
 14	  // garage east wall (x18): mudroom door, bonus arch, pantry and bedroom 4 windows
 15	  [18, 18, 2, 3, 17, 18], [18, 18, 7, 9, 14, 15], [18, 18, 3, 5, 23, 25], [18, 18, 7, 9, 23, 25],
 16	  // main front (z7): door and fanlight, office and bedroom 3 windows, foyer high window, bay mouth
 17	  [30, 31, 2, 5, 7, 7], [21, 23, 3, 5, 7, 7], [21, 23, 7, 9, 7, 7], [29, 32, 7, 9, 7, 7],
 18	  [38, 40, 2, 5, 7, 7], [38, 40, 7, 9, 7, 7],
 19	  // main east (x43): dining, family room and primary windows
 20	  [43, 43, 3, 5, 11, 13], [43, 43, 3, 5, 19, 21], [43, 43, 7, 9, 11, 13],
 21	  // main back (z28): slider, kitchen, bedroom 2 and primary bath windows
 22	  [37, 39, 2, 4, 28, 28], [29, 31, 3, 5, 28, 28], [29, 31, 7, 9, 28, 28], [37, 39, 7, 9, 28, 28],
 23	  // ground-floor doors and arches
 24	  [26, 26, 2, 3, 11, 11], [26, 26, 2, 3, 15, 15], [26, 26, 2, 3, 18, 18], [26, 26, 2, 3, 24, 24],
 25	  [35, 35, 2, 4, 11, 12], [30, 31, 2, 4, 16, 16],
 26	  // upper doors and arches
 27	  [22, 22, 7, 8, 13, 13], [22, 22, 7, 8, 16, 16], [30, 30, 7, 8, 16, 16], [39, 39, 7, 8, 16, 16],
 28	  [38, 38, 7, 8, 23, 23], [35, 35, 7, 9, 14, 15],
 29	];
 30	const OPEN = new Set();
 31	for (const [x0, x1, y0, y1, z0, z1] of OPENING_BOXES) {
 32	  for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) OPEN.add(`${x},${y},${z}`);
 33	}
 34	
 35	const isOpen = (x, y, z) => OPEN.has(`${x},${y},${z}`);
 36	const inChase = (x, z) => x >= CHIMNEY.x0 && x <= CHIMNEY.x1 && z >= CHIMNEY.z0 && z <= CHIMNEY.z1;
 37	// the foyer is double height: no floor-2 blocks over x27..34 z8..13, except the stair landing at x27..28 z13
 38	const inFoyerVoid = (x, z) => x >= 27 && x <= 34 && z >= 8 && z <= 13 && !(z === 13 && x <= 28);
 39	
 40	/** Places a block unless the cell is an opening (left air for later parts). */
 41	function place(g, x, y, z, block) {
 42	  if (!isOpen(x, y, z)) g.set(x, y, z, block);
 43	}
 44	
 45	/** Cells of the perimeter of the inclusive box x0..x1, z0..z1. */
 46	function perimeter(x0, x1, z0, z1) {
 47	  const cells = [];
 48	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
 49	    if (x === x0 || x === x1 || z === z0 || z === z1) cells.push([x, z]);
 50	  }
 51	  return cells;
 52	}
 53	
 54	/** Plinth: cobblestone at y0 under every outer wall (garage, main, entry sides, turret bay). */
 55	function plinth(g) {
 56	  for (const [x, z] of perimeter(0, 18, 5, 22)) g.set(x, 0, z, COBBLESTONE);
 57	  for (const [x, z] of perimeter(18, 43, 7, 28)) g.set(x, 0, z, COBBLESTONE);
 58	  for (const x of [26, 35]) for (const z of [5, 6]) g.set(x, 0, z, COBBLESTONE);
 59	  for (const [x, z] of perimeter(37, 41, 4, 7)) g.set(x, 0, z, COBBLESTONE);
 60	}
 61	
 62	/** Floors: garage y0 and bonus floor y6, main floor y1, upper floor y6 with the foyer void; ceilings y10. */
 63	function floors(g) {
 64	  for (let x = 1; x <= 17; x++) for (let z = 6; z <= 21; z++) {
 65	    g.set(x, 0, z, POLISHED_ANDESITE);
 66	    g.set(x, 6, z, OAK_PLANKS);
 67	    g.set(x, 10, z, SMOOTH_QUARTZ);
 68	  }
 69	  for (let x = 19; x <= 42; x++) for (let z = 8; z <= 27; z++) {
 70	    g.set(x, 1, z, SPRUCE_PLANKS);
 71	    if (!inChase(x, z) && !inFoyerVoid(x, z)) g.set(x, 6, z, OAK_PLANKS);
 72	    if (!inChase(x, z)) g.set(x, 10, z, SMOOTH_QUARTZ);
 73	  }
 74	}
 75	
 76	/** Outer walls y1..10: the garage ring, the main ring, and the entry's side walls; stone veneer y1..3 on the front. */
 77	function walls(g) {
 78	  for (const [x0, x1, z0, z1] of [[0, 18, 5, 22], [18, 43, 7, 28]]) {
 79	    for (const [x, z] of perimeter(x0, x1, z0, z1)) {
 80	      const front = z === z0 && x !== x0 && x !== x1;
 81	      for (let y = 1; y <= 10; y++) {
 82	        place(g, x, y, z, front && y <= 3 ? STONE_BRICKS : BIRCH_PLANKS);
 83	      }
 84	    }
 85	  }
 86	  for (const x of [26, 35]) for (const z of [5, 6]) {
 87	    for (let y = 1; y <= 10; y++) place(g, x, y, z, BIRCH_PLANKS);
 88	  }
 89	}
 90	
 91	/** Interior partitions (birch), full storey height, openings left out by place(). */
 92	function partitions(g) {
 93	  const solid = (x0, x1, y0, y1, z0, z1) => {
 94	    for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) place(g, x, y, z, BIRCH_PLANKS);
 95	  };
 96	  // main floor, y2..5
 97	  solid(26, 26, 2, 5, 8, 28);
 98	  solid(35, 35, 2, 5, 8, 16);
 99	  solid(27, 42, 2, 5, 16, 16);
100	  solid(19, 25, 2, 5, 13, 13);
101	  solid(19, 25, 2, 5, 20, 20);
102	  // upper floor, y7..9
103	  solid(26, 26, 7, 9, 8, 13);
104	  solid(26, 26, 7, 9, 16, 27);
105	  solid(35, 35, 7, 9, 8, 13);
106	  solid(35, 35, 7, 9, 16, 27);
107	  solid(19, 25, 7, 9, 13, 13);
108	  solid(19, 42, 7, 9, 16, 16);
109	  solid(36, 42, 7, 9, 23, 23);
110	}
111	
112	/** The massing: plinth, floors, outer walls, partitions and ceilings; then the turret bay and the main staircase. */
113	export function build(g) {
114	  plinth(g);
115	  floors(g);
116	  walls(g);
117	  partitions(g);
118	  bay(g);
119	  mainStair(g);
120	}

