     1	// Part 6: Chimney, dormers and details. Stone chimney shaft with its cap and pots (element 14), the three gabled dormers
     2	// (element 5), hip finials on the flat roof decks, and two planters on the back deck. Builds only into air: the roof
     3	// holes P2 leaves for the chimney and dormers are the cells it fills.
     4	import { chimney, dormer, LIGHTNING_ROD, DORMERS } from "../vocab.mjs";
     5	
     6	// Hip finials: a lightning rod on the centre of each flat hip deck (garage deck x2..16 z7..20, main deck x20..41 z9..26).
     7	const HIP_FINIALS = [[9, 14, 13], [30, 14, 17]];
     8	
     9	// Deck planters: a rose bush and a peony, two-block plants on the deck planks at y2..3, clear of the rails.
    10	const PLANTERS = [
    11	  { block: "rose_bush", x: 31, z: 29 },
    12	  { block: "peony", x: 41, z: 29 },
    13	];
    14	
    15	export function build(g) {
    16	  // Chimney shaft x40..42 z24..26, y2..13 in stone brick, y14 cap with the two pots at (40,25) and (42,25).
    17	  chimney(g);
    18	
    19	  // Gabled dormers: two on the street slope, one on the rear slope (dz -1 walks back toward the rear wall).
    20	  for (const d of DORMERS) dormer(g, d.x, d.z, d.dz, d.depth);
    21	
    22	  for (const [x, y, z] of HIP_FINIALS) g.set(x, y, z, LIGHTNING_ROD, { facing: "up", powered: "false" });
    23	
    24	  for (const p of PLANTERS) {
    25	    g.set(p.x, 2, p.z, p.block, { half: "lower" });
    26	    g.set(p.x, 3, p.z, p.block, { half: "upper" });
