     2	// Layout: birch island dresser (focal) centred under a hanging lantern; iron-bar rails hang from the east and west
     3	// walls over shelf stacks; stair seats at the island; a spruce vanity on the south wall; lanterns for light.
     4	// Aisles stay open: x37 and x41 run the full depth, z18 and z21 cross the room, and the door cell (39,17) is free.
     5	import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
     6	
     7	const BIRCH_PLANKS = "birch_planks";
     8	const SPRUCE_PLANKS = "spruce_planks";
