     2	// Front (z6..12): three open car bays in front of the carriage doors, kept clear. Back (z13..21): work zone grouped by use:
     3	// a cabinet run on the west wall, a workbench (focal, under a hanging lantern) with a tool wall above it on the back wall,
     4	// a cabinet and tool wall at the back-left, a water heater in the back-right corner and a bike rail on the east side.
     5	// The mudroom step (17,1,17..18) rises east to the door at x18 y2..3. Light: hanging lanterns from the y6 ceiling.
     6	import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
     7	
     8	const SPRUCE_PLANKS = "spruce_planks";
     9	const SPRUCE_SLAB = "spruce_slab";
    10	const IRON_BARS = "iron_bars";
    11	const WHITE_CONCRETE = "white_concrete";
    12	const SMOOTH_STONE_SLAB = "smooth_stone_slab";
    13	
    14	// Iron bars as a pegboard on a wall: connects to the wall behind (south) and to its neighbours (east/west).
    15	const bars = (north = false, south = true, east = true, west = true) =>
    16	  [IRON_BARS, { north: String(north), south: String(south), east: String(east), west: String(west), waterlogged: "false" }];
    17	
    18	export function build(g) {
    19	  // Mudroom step: two stairs at x17 y1 rising east onto the door sill (x18 y2).
    20	  for (const z of [17, 18]) g.set(17, 1, z, ...B.stairs("spruce", "east", "bottom"));
    21	
    22	  // West cabinet run: planks cabinets at y1 with a slab shelf above on x1, z13..17.
    23	  for (let z = 13; z <= 17; z++) {
    24	    g.set(1, 1, z, SPRUCE_PLANKS);
    25	    g.set(1, 2, z, ...B.slab("spruce", "bottom"));
    26	  }
    27	
    28	  // Back-left: cabinet under a tool wall at x2..5 z21.
    29	  g.fill([2, 1, 21], [5, 1, 21], SPRUCE_PLANKS);
    30	  for (let x = 2; x <= 5; x++) for (const y of [2, 3, 4]) g.set(x, y, 21, ...bars());
    31	
    32	  // Focal workbench: planks counter at y1 with a slab top at y2, x7..11 z21, tool wall above it at y3..4.
    33	  g.fill([7, 1, 21], [11, 1, 21], SPRUCE_PLANKS);
    34	  for (let x = 7; x <= 11; x++) g.set(x, 2, 21, ...B.slab("spruce", "bottom"));
    35	  for (let x = 7; x <= 11; x++) for (const y of [3, 4]) if (!(x === 9 && y === 3)) g.set(x, y, 21, ...bars());
    36	  g.set(9, 3, 21, ...B.lantern(false));   // bench lamp: stands on the slab top, in place of the centre bar
    37	
    38	  // Back-right: water heater (white tank, smooth slab cap) at x17 z21.
    39	  g.set(17, 1, 21, WHITE_CONCRETE);
    40	  g.set(17, 2, 21, WHITE_CONCRETE);
    41	  g.set(17, 3, 21, SMOOTH_STONE_SLAB, { type: "bottom", waterlogged: "false" });
    42	
    43	  // East bike rail at x15 z13..16: iron bars running north-south on y1 and y2 posts.
    44	  for (let z = 13; z <= 16; z++) g.set(15, 1, z, ...bars(z > 13, z < 16, false, false));
    45	
    46	  // Hanging lanterns from the y6 ceiling: one over each car bay, one over the workbench, two over the work zone.
    47	  for (const [x, z] of [[3, 9], [8, 9], [13, 9], [3, 13], [8, 13], [13, 13], [6, 17], [11, 17], [3, 20], [9, 20], [14, 20]]) {
    48	    g.set(x, 5, z, ...B.lantern(true));
    49	  }
    50	}
