     1	// Room 11: Bedroom 4, interior designer. Inner air x19..25, y7..9, z17..27; door (22, y7..8, z16) from the upper hall;
     2	// west window (18, y7..9, z23..25). Palette has no bed, carpet, barrel or flower pot, so the room is a reading and
     3	// work room: a window desk with a chair, a reading corner, a wardrobe of open trapdoors, a shelf run and lanterns.
     4	import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
     5	
     6	const SPRUCE_FENCE = "spruce_fence";
     7	const SPRUCE_SLAB = "spruce_slab";
     8	const LANTERN = "lantern";
     9	
    10	export function build(g) {
    11	  // Workstation under the west window: fence legs at y7, slab top at y8 (the desk), chair on the room side.
    12	  for (let z = 23; z <= 25; z++) {
    13	    g.set(19, 7, z, SPRUCE_FENCE);
    14	    g.set(19, 8, z, ...B.slab("spruce", "top"));
    15	  }
    16	  g.set(19, 9, 24, LANTERN, { hanging: "false", waterlogged: "false" });   // desk lamp on the slab top
    17	  g.set(20, 7, 24, ...B.stairs("spruce", "east", "bottom"));              // desk chair: back east, seat faces the desk
    18	
    19	  // Wardrobe: two open spruce trapdoor panels, two high, on the east wall (x26), facing into the room.
    20	  for (let z = 18; z <= 19; z++) for (let y = 7; y <= 8; y++) g.set(25, y, z, ...B.trapdoor("spruce", "west", "bottom", true));
    21	
    22	  // Shelf run on the north wall (z16): slabs at y8 beside the door, clear of the doorway.
    23	  for (let x = 19; x <= 21; x++) g.set(x, 8, 17, ...B.slab("spruce", "bottom"));
    24	
    25	  // Reading corner in the south-east: side table with a lamp, two stair seats either side of it.
    26	  g.set(23, 7, 26, SPRUCE_FENCE);
    27	  g.set(23, 8, 26, ...B.slab("spruce", "top"));
    28	  g.set(23, 9, 26, LANTERN, { hanging: "false", waterlogged: "false" });
    29	  g.set(22, 7, 26, ...B.stairs("spruce", "west", "bottom"));              // seat faces east toward the table
    30	  g.set(24, 7, 26, ...B.stairs("spruce", "east", "bottom"));              // seat faces west toward the table
    31	
    32	  // Floor lamps: fence post with a standing lantern, one in each back corner.
    33	  g.set(19, 7, 20, SPRUCE_FENCE);
    34	  g.set(19, 8, 20, LANTERN, { hanging: "false", waterlogged: "false" });
    35	  g.set(25, 7, 22, SPRUCE_FENCE);
    36	  g.set(25, 8, 22, LANTERN, { hanging: "false", waterlogged: "false" });
    37	
    38	  // Ceiling lantern on a chain over the middle of the room.
    39	  g.set(22, 9, 22, ...B.chain("y"));
    40	  g.set(22, 8, 22, LANTERN, { hanging: "true", waterlogged: "false" });
    41	}

