input.command:
cd /tmp/bld && cat > /tmp/bld/slabs.mjs <<'EOF'
// slabs.mjs: list positions of a block name in a structure nbt, with y range. Usage: node slabs.mjs file.nbt block
import { readFileSync } from "node:fs";
import { parse, simplify } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/nbt.mjs";
const [file, want] = process.argv.slice(2);
const d = simplify(parse(readFileSync(file)).tag);
const pal = d.palette.map((p) => p.Name.replace("minecraft:", ""));
const hits = d.blocks.filter((b) => pal[b.state] === want).map((b) => b.pos);
const ys = [...new Set(hits.map((p) => p[1]))].sort((a, b) => a - b);
console.log(file, want, "count", hits.length, "y values", ys.join(","));
const hi = hits.filter((p) => p[1] >= 10);
console.log("y>=10:", hi.length, hi.slice(0, 12).map((p) => p.join(",")).join(" | "));
EOF
node slabs.mjs raw.nbt spruce_slab; node slabs.mjs t-a.nbt spruce_slab; node slabs.mjs t-b.nbt spruce_slab

